import{initializeApp}from"https://www.gstatic.com/firebasejs/10.8.1/firebase-app.js";import{getFirestore,collection,addDoc,onSnapshot,query,orderBy,serverTimestamp}from"https://www.gstatic.com/firebasejs/10.8.1/firebase-firestore.js";const firebaseConfig={apiKey:"AIzaSyBURLQ0kyhvnQSv56GGFsglTmrXaVrGdcY",authDomain:"reddevils-db.firebaseapp.com",projectId:"reddevils-db",storageBucket:"reddevils-db.firebasestorage.app",messagingSenderId:"707657666793",appId:"1:707657666793:web:81c0f594cb47ed675e2078",measurementId:"G-BPC8WVGQQN"};const app=initializeApp(firebaseConfig);const db=getFirestore(app);async function fetchESPNTable(){const e="https://site.api.espn.com/apis/v2/sports/soccer/eng.1/standings",t=document.getElementById("pl-table-container");if(!t)return;try{const a=await fetch(e);if(!a.ok)throw new Error(`Server returned ${a.status}`);const s=await a.json(),n=s.children[0].standings.entries;let o='<table class="pl-table"><thead><tr><th>Pos</th><th>Club</th><th>MP</th><th>GD</th><th>Pts</th></tr></thead><tbody>';n.forEach(e=>{const t=e.team,a=e.stats,s=a.find(e=>"rank"===e.type)?.displayValue,n=a.find(e=>"gamesplayed"===e.type)?.displayValue,r=a.find(e=>"pointdifferential"===e.type)?.displayValue,i=a.find(e=>"points"===e.type)?.displayValue,l="360"===t.id?'class="highlight-united"':"";o+=`<tr ${l}><td>${s}</td><td class="team-cell"><img src="${t.logos[0].href}" alt="" class="table-logo" loading="lazy"> ${t.displayName}</td><td>${n}</td><td>${r}</td><td>${i}</td></tr>`}),o+="</tbody></table>",void 0!==typeof DOMPurify?t.innerHTML=DOMPurify.sanitize(o):(()=>{throw new Error("DOMPurify failed to load.")})()}catch(e){console.error("API Error:",e),t.innerHTML=`<div class='loading'>Failed to load live data. <br><small style="color: var(--red);">Error: ${e.message}</small></div>`}}function initGuestbook(){const e=document.getElementById("guestbook-form"),t=document.getElementById("guestbook-messages");if(!e||!t)return;const a=query(collection(db,"guestbook"),orderBy("createdAt","desc"));onSnapshot(a,e=>{t.innerHTML="",e.forEach(e=>{const a=e.data(),s=a.createdAt?a.createdAt.toDate().toLocaleString():"Just now",n=void 0!==typeof DOMPurify?DOMPurify.sanitize(a.name):a.name,o=void 0!==typeof DOMPurify?DOMPurify.sanitize(a.message):a.message;t.innerHTML+=`\n        <div class="gb-message-card">\n          <div class="gb-name">${n}</div>\n          <p class="gb-text">${o}</p>\n          <div class="gb-date">${s}</div>\n        </div>\n      `})},e=>{t.innerHTML='<div class="loading">Connect your Firebase database to see messages.</div>'}),e.addEventListener("submit",async t=>{t.preventDefault();const a=document.getElementById("gb-name"),s=document.getElementById("gb-message"),n=document.getElementById("gb-submit");n.disabled=!0,n.textContent="Posting...";try{await addDoc(collection(db,"guestbook"),{name:a.value,message:s.value,createdAt:serverTimestamp()}),a.value="",s.value=""}catch(e){alert("Failed to post message. Ensure your Firebase Config is pasted in script.js!")}finally{n.disabled=!1,n.textContent="Post Message"}})}document.addEventListener("DOMContentLoaded",()=>{fetchESPNTable(),initGuestbook()});